/* 02 · Built on their work (mock-up: built.css): the ribbon diagram (desktop) and its stacked form (phone). */
.tp-scholars :where(.tp-sec-built button) { padding: 0; border: 0; background: none; text-align: left; font: inherit; color: inherit; cursor: pointer; }

.tp-scholars .blt-card { position: relative; padding: 1.1rem 1.4rem 1.2rem; border: 1px solid var(--line); border-radius: 1.5rem;
  background: radial-gradient(ellipse 50% 70% at 8% 0%, color-mix(in srgb, var(--accent) 8%, transparent), transparent 70%),
    radial-gradient(ellipse 40% 60% at 96% 100%, color-mix(in srgb, var(--prophets) 7%, transparent), transparent 70%), var(--surface);
  box-shadow: 0 30px 60px -48px rgb(0 0 0 / 45%); }

/* Caption: a fixed two-line bar, so hovering never moves the page. */
.tp-scholars .blt-cap { display: flex; gap: .7rem; align-items: flex-start; height: 3.3rem; overflow: hidden; padding-bottom: .8rem; border-bottom: 1px solid var(--line); }
.tp-scholars .blt-cap-dot { flex: none; width: 7px; height: 7px; margin-top: .45rem; border-radius: 50%; background: var(--cap-tone, var(--accent));
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--cap-tone, var(--accent)) 18%, transparent); transition: background .2s, box-shadow .2s; }
.tp-scholars .blt-cap-text { min-width: 0; margin: 0; overflow: hidden; font-size: .92rem; line-height: 1.45; white-space: nowrap; text-overflow: ellipsis; }
.tp-scholars .blt-cap-text b { font: 500 1rem var(--serif); }
.tp-scholars .blt-cap-hint { color: var(--muted); font-size: .84rem; }
.tp-scholars .blt-arrow { color: var(--cap-tone, var(--accent)); font-weight: 600; }
.tp-scholars .blt-cap-note { display: block; overflow: hidden; margin-top: .1rem; font-size: .78rem; color: var(--muted); white-space: nowrap; text-overflow: ellipsis; }

/* ── Desktop stage ───────────────────────────────────────────────────────── */
.tp-scholars .blt-stage { position: relative; margin-top: .4rem; }
.tp-scholars .blt-art { position: absolute; inset: 0; display: block; width: 100%; height: 100%; overflow: visible; clip-path: inset(0 100% 0 0); }
.tp-scholars .blt-in .blt-art { clip-path: inset(0 0 0 0); transition: clip-path 1.5s cubic-bezier(.65, 0, .35, 1) .15s; }
.tp-scholars .blt-rib { fill: none; stroke: var(--tone); stroke-width: 11; stroke-opacity: .34; cursor: pointer; transition: stroke-opacity .25s; }
.tp-scholars .blt-rib.blt-planned { stroke: var(--muted); stroke-opacity: .26; stroke-dasharray: 3 3; }
.tp-scholars .blt-con { fill: none; stroke: var(--line); stroke-width: 1.25; stroke-dasharray: 2 3; transition: stroke .25s, stroke-width .25s; }
.tp-scholars .blt-dim .blt-rib { stroke-opacity: .08; }
.tp-scholars .blt-dim .blt-rib.blt-on { stroke-opacity: .85; }
.tp-scholars .blt-dim .blt-rib.blt-planned.blt-on { stroke-opacity: .6; }
.tp-scholars .blt-dim .blt-con.blt-on { stroke: var(--ink); stroke-dasharray: none; }

.tp-scholars .blt-col { position: absolute; top: 0; font-size: .6rem; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: var(--muted); }
.tp-scholars :is(.blt-feat, .blt-work, .blt-sch) { position: absolute; transition: opacity .45s, transform .6s cubic-bezier(.16, 1, .3, 1); }
.tp-scholars .blt-card:not(.blt-in) :is(.blt-feat, .blt-work, .blt-sch) { opacity: 0; }
.tp-scholars .blt-card:not(.blt-in) .blt-feat { transform: translateX(-10px); }
.tp-scholars .blt-card:not(.blt-in) :is(.blt-work, .blt-sch) { transform: translateX(10px); }
.tp-scholars .blt-in .blt-work { transition-delay: .55s; }
.tp-scholars .blt-in .blt-sch { transition-delay: calc(.8s + var(--i) * 25ms); }
.tp-scholars .blt-in.blt-settled :is(.blt-work, .blt-sch) { transition-delay: 0s; }

/* Feature nodes: label to the left of a tone bar the ribbons leave from. */
.tp-scholars .blt-feat { display: flex; flex-direction: column; justify-content: center; align-items: flex-end; padding-right: 18px; text-align: right; }
.tp-scholars .blt-feat b { font: 500 1.08rem/1.2 var(--serif); letter-spacing: -.01em; }
.tp-scholars .blt-feat small { margin-top: .15rem; font-size: .7rem; color: var(--muted); }
.tp-scholars .blt-feat i { position: absolute; top: 0; right: 0; bottom: 0; width: 6px; border-radius: 3px; background: var(--tone); transition: box-shadow .25s; }
.tp-scholars .blt-feat.blt-planned i { background: repeating-linear-gradient(180deg, var(--muted) 0 3px, transparent 3px 6px); opacity: .7; }
.tp-scholars .blt-feat:hover b, .tp-scholars .blt-feat[aria-pressed="true"] b { color: color-mix(in srgb, var(--tone) 70%, var(--ink)); }
.tp-scholars .blt-feat[aria-pressed="true"] i { box-shadow: 0 0 0 3px color-mix(in srgb, var(--tone) 22%, transparent); }

/* Books: a slim bar where the ribbons land, then the title and year. */
.tp-scholars .blt-work { display: grid; grid-template-columns: 4px minmax(0, 1fr); grid-template-rows: auto auto; column-gap: 12px; align-content: center; }
.tp-scholars .blt-work i { grid-row: 1 / 3; align-self: stretch; border-radius: 2px; background: color-mix(in srgb, var(--ink) 55%, transparent); }
.tp-scholars .blt-work.blt-planned i { background: color-mix(in srgb, var(--muted) 45%, transparent); }
.tp-scholars .blt-work span { overflow: hidden; font: 500 .92rem/1.2 var(--serif); white-space: nowrap; text-overflow: ellipsis; }
.tp-scholars .blt-work small { font-size: .68rem; color: var(--muted); font-variant-numeric: tabular-nums; }

/* Scholars: mark, name, years and faith. */
.tp-scholars .blt-sch { display: flex; gap: .6rem; align-items: center; padding-left: 2px; }
.tp-scholars .blt-sch > svg { transition: transform .3s cubic-bezier(.16, 1, .3, 1); }
.tp-scholars .blt-sch > span:last-child { min-width: 0; }
.tp-scholars .blt-sch b { display: block; overflow: hidden; font: 500 .9rem/1.2 var(--serif); white-space: nowrap; text-overflow: ellipsis; }
.tp-scholars .blt-sch small { display: block; overflow: hidden; font-size: .68rem; color: var(--muted); white-space: nowrap; text-overflow: ellipsis; }
.tp-scholars :is(.blt-sch:hover, .blt-sch.blt-on) > svg { transform: scale(1.12); }
.tp-scholars :is(.blt-sch:hover, .blt-sch.blt-on) b { color: color-mix(in srgb, var(--tone) 70%, var(--ink)); }

.tp-scholars .blt-dim :is(.blt-feat, .blt-work, .blt-sch):not(.blt-on) { opacity: .32; }
.tp-scholars .blt-dim .blt-work.blt-on i { background: var(--ink); }

.tp-scholars .blt-legend { display: flex; flex-wrap: wrap; gap: .4rem 1.4rem; margin: 1rem 0 0; padding: .8rem 0 0; border-top: 1px solid var(--line); list-style: none; font-size: .74rem; color: var(--muted); }
.tp-scholars .blt-legend li { display: inline-flex; gap: .5rem; align-items: center; }
.tp-scholars .blt-legend li:last-child { margin-left: auto; }
.tp-scholars .blt-legend i { width: 22px; height: 7px; border-radius: 2px; }
.tp-scholars .blt-key-live { background: linear-gradient(90deg, var(--poetry), var(--acts), var(--gospels), var(--epistles)); opacity: .7; }
.tp-scholars .blt-key-planned { background: repeating-linear-gradient(90deg, var(--muted) 0 3px, transparent 3px 6px); opacity: .6; }

/* ── Phone: one list per feature, each book branching off the feature's rail ── */
.tp-scholars .blt-stack { display: none; }
@media (max-width: 760px) {
  .tp-scholars .blt-card { padding: 1rem 1rem 1.1rem; border-radius: 1.1rem; }
  .tp-scholars .blt-stage { display: none; }
  .tp-scholars .blt-cap { display: none; }
  .tp-scholars .blt-stack { display: grid; gap: 1.3rem; }
  .tp-scholars .blt-legend li:last-child { margin-left: 0; }
}
.tp-scholars .blt-st-group { transition: opacity .5s, transform .6s cubic-bezier(.16, 1, .3, 1); }
.tp-scholars .blt-card:not(.blt-in) .blt-st-group { opacity: 0; transform: translateY(10px); }
.tp-scholars .blt-st-group h3 { display: flex; gap: .55rem; align-items: center; margin: 0; font: 500 1.15rem/1.2 var(--serif); }
.tp-scholars .blt-st-group h3 i { width: 10px; height: 10px; border-radius: 3px; background: var(--tone); }
.tp-scholars .blt-st-group.blt-planned h3 i { background: none; border: 1.5px dashed var(--muted); }
.tp-scholars .blt-st-group h3 small { margin-left: auto; font: 600 .6rem var(--sans); letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }
.tp-scholars .blt-st-group ul { margin: .35rem 0 0; padding: 0 0 0 1.6rem; list-style: none; }
.tp-scholars .blt-st-group li { position: relative; }
.tp-scholars .blt-st-group li::before { content: ""; position: absolute; left: -1.15rem; top: 0; width: .85rem; height: 1.45rem; border-left: 2px solid var(--tone); border-bottom: 2px solid var(--tone);
  border-bottom-left-radius: .7rem; opacity: .55; }
.tp-scholars .blt-st-group li:not(:last-child)::after { content: ""; position: absolute; left: -1.15rem; top: 1.2rem; bottom: 0; border-left: 2px solid var(--tone); opacity: .55; }
.tp-scholars .blt-st-group.blt-planned li::before, .tp-scholars .blt-st-group.blt-planned li:not(:last-child)::after { border-style: dashed; border-color: var(--muted); }
.tp-scholars .blt-st-group button { display: grid; gap: .35rem; width: 100%; padding: .55rem .6rem; border-radius: .7rem; transition: background .15s; }
.tp-scholars .blt-st-group button:hover { background: var(--surface-2); }
.tp-scholars .blt-st-work { font: 500 .95rem/1.3 var(--serif); }
.tp-scholars .blt-st-work em { font: 400 .78rem var(--sans); font-style: normal; color: var(--muted); }
.tp-scholars .blt-st-who { display: flex; gap: .55rem; align-items: center; min-width: 0; }
.tp-scholars .blt-st-who > span:last-child { min-width: 0; }
.tp-scholars .blt-st-who b { display: block; font: 500 .84rem/1.2 var(--sans); }
.tp-scholars .blt-st-who small { display: block; font-size: .7rem; color: var(--muted); }

@media (prefers-reduced-motion: reduce) {
  .tp-scholars .blt-art { clip-path: none; }
}

/* The same ribbon stage, bounded so the complete source index can be explored. */
.tp-scholars .blt-scroll { max-height: 70vh; overflow: auto; }
.tp-scholars .blt-stack { max-height: 70vh; overflow-y: auto; }
.tp-scholars .blt-work { color: var(--ink); text-decoration: none; }
.tp-scholars .blt-st-group a { display: block; width: 100%; color: inherit; text-decoration: none; }

