import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { mergeLibrary, matchesLibrary, orderLibrary, ALL_LIBRARY, type LibrarySort } from './library';
import { NO_FILTERS } from '../context';
import type { ScholarsData } from '@/data/teachers/pages-types';
import type { FieldLibrary } from '../field-library';
import type { AcquiredCatalogue } from '../../shared/acquired';

const read = (path: string) => JSON.parse(readFileSync(path, 'utf8'));
const acquired: AcquiredCatalogue = read('public/content/teacher-library/catalogue.json');
const fields: FieldLibrary = read('content/teachers/field-shelves.json');
const data: ScholarsData = read('src/data/teachers/scholars.json');
const people = mergeLibrary(fields, acquired, data);
describe('complete contributor catalogue against the acquired corpus', () => {
  it('represents every acquired contributor exactly once and retains every documented scholar', () => {
    const ids = people.flatMap(p => p.contributorIds);
    expect(new Set(ids).size).toBe(acquired.contributors.length);
    expect(ids.length).toBe(new Set(ids).size);
    expect(new Set(ids)).toEqual(new Set(acquired.contributors.map(c => c.id)));
    expect(people.filter(p => p.scholar).map(p => p.scholar!.id).sort()).toEqual(data.scholars.map(s => s.id).sort());
    expect(new Set(people.map(p => p.id)).size).toBe(people.length);
  });
  it('includes unclassified credits without inventing fields or biographies', () => {
    const found = people.filter(p => matchesLibrary(p, NO_FILTERS, { ...ALL_LIBRARY, unclassified: true }));
    expect(found.length).toBe(fields.coverage.withoutSubjectMatch);
    expect(found.every(p => !p.scholar && !Object.keys(p.fields).length)).toBe(true);
    expect(people.length).toBe(fields.entries.length + found.length);
    expect(people.filter(p => matchesLibrary(p, { ...NO_FILTERS, q: found[0].name.toLowerCase() }, ALL_LIBRARY))).toContain(found[0]);
  });
  it('retains all CCEL and Latin Fathers contributors and their shelf evidence', () => {
    for (const collection of ['ccel', 'latin-fathers']) {
      const found = people.filter(p => matchesLibrary(p, NO_FILTERS, { ...ALL_LIBRARY, collection }));
      expect(found.length).toBe(fields.coverage.collections[collection]);
      expect(found.every(p => p.contributorIds.length || p.supplements.length)).toBe(true);
    }
    expect(people.find(p => p.name === 'Ambrose of Milan')?.supplements.length).toBeGreaterThan(0);
  });
  it('keeps the complete set in every sort and separates profile status from library records', () => {
    const ids = people.map(p => p.id).sort();
    for (const sort of ['featured', 'year', 'held', 'az', 'named'] as LibrarySort[]) expect(orderLibrary(people, sort).map(p => p.id).sort()).toEqual(ids);
    expect(people.filter(p => matchesLibrary(p, NO_FILTERS, { ...ALL_LIBRARY, scope: 'profiles' }))).toHaveLength(data.scholars.length);
    expect(people.filter(p => matchesLibrary(p, { ...NO_FILTERS, used: true }, ALL_LIBRARY)).length).toBe(data.scholars.filter(s => s.site?.status === 'in-use').length);
  });
});

import { usedEntry } from "../site-evidence";
import type { Scholar, ScholarsData } from '@/data/teachers/pages-types';
import type { AcquiredCatalogue } from '../../shared/acquired';
import type { FieldEntry, FieldLibrary } from '../field-library';
import type { ContributorFact, ContributorFacts } from '../facts';
import type { CatalogueFilters } from '../context';
import { weight } from '../marks/facts';
import featured from '../../../../../content/teachers/field-featured.json';

export interface LibraryPerson extends FieldEntry { scholar?: Scholar; facts?: ContributorFact; search: string; sourceLifeDates: string[] }
export interface LibraryOptions { collection: string; role: string; scope: string; unclassified: boolean; unknownEra: boolean }
export const ALL_LIBRARY: LibraryOptions = { collection: '', role: '', scope: '', unclassified: false, unknownEra: false };
export type LibrarySort = 'featured' | 'az' | 'year' | 'held' | 'named';

/** Retain every source credit, including names with no assigned field. Only previously verified aliases are merged. */
export function mergeLibrary(index: FieldLibrary, acquired: AcquiredCatalogue, data: ScholarsData, facts?: ContributorFacts): LibraryPerson[] {
  const entries: FieldEntry[] = index.entries.map(p => ({ ...p }));
  const covered = new Set(entries.flatMap(p => p.contributorIds));
  for (const c of acquired.contributors) if (!covered.has(c.id)) entries.push({
    id: c.id, name: c.name, profileId: c.profileId, aliases: [c.name], contributorIds: [c.id],
    roles: c.roles, traditions: c.traditions, collections: [], fields: {}, records: c.records, readable: c.readable, supplements: [],
  });
  const sources = new Map(acquired.contributors.map(c => [c.id, c]));
  const profiles = new Map(data.scholars.map(s => [s.id, s]));
  return entries.map(p => {
    const scholar = profiles.get(p.profileId ?? '');
    const sourceLifeDates = [...new Set(p.contributorIds.flatMap(id => sources.get(id)?.sourceLifeDates ?? []))];
    const search = [p.name, ...p.aliases, ...p.roles, ...p.traditions, ...sourceLifeDates,
      ...Object.entries(p.fields).flatMap(([key, field]) => [data.fields[key as keyof typeof data.fields], field?.example?.title]),
      ...(scholar ? [scholar.short, scholar.place[0], scholar.line, ...scholar.works.map(w => w[0]), ...(scholar.tags ?? [])] : []),
    ].join(' ').toLocaleLowerCase();
    return { ...p, scholar, search, sourceLifeDates, facts: facts?.entries[p.id] };
  });
}

export function matchesLibrary(p: LibraryPerson, f: CatalogueFilters, o: LibraryOptions, ignore = ''): boolean {
  if (ignore !== 'field' && f.field.length && !f.field.some(key => p.fields[key])) return false;
  if (ignore !== 'era' && f.era.length && !f.era.includes((p.facts?.dates.era ?? p.scholar?.era ?? "unknown") as typeof f.era[number])) return false;
  if (ignore !== 'faith' && f.faith.length && !f.faith.includes(p.facts?.faith ?? p.scholar?.faith ?? 'unrecorded')) return false;
  if (ignore !== 'used' && f.used && !usedEntry(p)) return false;
  if (o.collection && !p.collections.includes(o.collection)) return false;
  if (o.role && !p.roles.includes(o.role)) return false;
  if (o.scope === 'profiles' && !p.scholar || o.scope === 'library' && p.scholar) return false;
  if (o.unclassified && Object.keys(p.fields).length) return false;
  if (o.unknownEra && (p.facts?.dates.era ?? p.scholar?.era)) return false;
  return f.q.split(/\s+/).filter(Boolean).every(word => p.search.includes(word));
}

const featuredIds = new Set(Object.values(featured).flat().map(([id]) => id));
export function orderLibrary(people: LibraryPerson[], sort: LibrarySort): LibraryPerson[] {
  const rank = (p: LibraryPerson) => p.scholar ? 0 : featuredIds.has(p.id) ? 1 : 2;
  return [...people].sort((a, b) => {
    if (sort === 'az') return a.name.localeCompare(b.name) || a.id.localeCompare(b.id);
    if (sort === 'featured') return rank(a) - rank(b) || (a.scholar && b.scholar ? a.scholar.born - b.scholar.born : 0) || b.records - a.records || a.name.localeCompare(b.name);
    if (sort === 'year') return (a.facts?.dates.born ?? a.facts?.dates.floruit ?? a.scholar?.born ?? Infinity) - (b.facts?.dates.born ?? b.facts?.dates.floruit ?? b.scholar?.born ?? Infinity) || a.name.localeCompare(b.name);
    if (sort === 'named') return (b.scholar ? weight(b.scholar) : 0) - (a.scholar ? weight(a.scholar) : 0) || a.name.localeCompare(b.name);
    return b.records - a.records || a.name.localeCompare(b.name);
  });
}

