// The finds list's cards: the "All 7" summary, and one card per find carrying its "from the dig to your screen" thread
// (who found or studied it → what came of it → where it reaches this site, or that it does not yet).
import { ArrowRight, ArrowUpRight } from "lucide-react";
import { Link } from "react-router-dom";
import type { Find, Scholar } from "@/data/teachers/pages-types";
import { useScholars } from "../context";
import { AREA_ROUTE, areaOf, discoveryEvidence, cssVars, overviewOf, toneOf, type DiscoveryModel, type Step } from "./model";

interface CardProps { on: boolean; onChoose: () => void }

export function OverviewCard({ model, on, onChoose }: CardProps & { model: DiscoveryModel }) {
  const words = overviewOf(model);
  return <article className={`dsc-find dsc-find-all${on ? " dsc-on" : ""}`}>
    <button type="button" className="dsc-find-hit" aria-label={`Show all ${model.finds.length} discoveries`} onClick={onChoose} />
    <div className="dsc-find-top"><span className="dsc-year">{words.span}</span><span className="dsc-where">All {model.finds.length}</span></div>
    <h3>{words.title}</h3>
    <p>{words.from} {words.lie}</p>
    <div className="dsc-sum"><p className="dsc-step-k">From the dig to your screen</p><p>{words.reach}</p></div>
    <p className="dsc-find-hint">Scroll the list, or choose one.</p>
  </article>;
}

export function FindCard({ model, find, on, onChoose }: CardProps & { model: DiscoveryModel; find: Find }) {
  return <article className={`dsc-find${on ? " dsc-on" : ""}`}>
    <button type="button" className="dsc-find-hit" aria-label={`Show ${find.name} on the map`} onClick={onChoose} />
    <div className="dsc-find-top">
      <span className="dsc-year">{discoveryEvidence[find.id].date}</span>
      <span className="dsc-where">{find.where[0]}{model.inHoly.has(find.id) ? null : <> <em>· beyond this map</em></>}</span>
    </div>
    <h3>{find.name}</h3>
    <p>{find.line}</p>
    <div className="dsc-thread">
      <p className="kicker">From the dig to your screen</p>
      <ol>{model.threads[find.id].steps.map((step, n) => <ThreadStep key={n} step={step} />)}</ol>
    </div>
  </article>;
}

function ThreadStep({ step }: { step: Step }) {
  switch (step.kind) {
    case "who": return <li className="dsc-step"><p className="dsc-step-k">{step.role ?? "Found or studied by"}</p><Chip scholar={step.scholar} /></li>;
    case "came": return <li className="dsc-step"><p className="dsc-step-k">Documented source</p><p className="dsc-step-v">{step.url ? <a className="dsc-site-link" href={step.url} target="_blank" rel="noreferrer">{step.work[0]}</a> : <i>{step.work[0]}</i>} {step.work[1]}</p></li>;
    case "next": return <li className="dsc-step">
      <p className="dsc-step-k">Scholar cited on the site</p><Chip scholar={step.scholar} /><p className="dsc-step-v dsc-step-sub">{step.what}</p>
    </li>;
    case "none": return <li className="dsc-step dsc-step-none"><p className="dsc-step-k">On this site</p><p className="dsc-step-v">No feature connection verified in this review.</p></li>;
    case "site": {
      const area = step.label ?? areaOf(step.scholar);
      return <li className="dsc-step dsc-step-site">
        <p className="dsc-step-k">{step.site.status === "in-use" ? "Where it reaches this site" : "Held in the library"}</p>
        {area && <Link className="dsc-site-link" to={step.url ?? AREA_ROUTE[area]}>{area}<ArrowUpRight size={14} aria-hidden="true" /></Link>}
        <p className="dsc-step-v dsc-step-sub">{step.site.note}</p>
      </li>;
    }
  }
}

function Chip({ scholar }: { scholar: Scholar }) {
  const { data, openProfile } = useScholars();
  return <button type="button" className="dsc-chip" style={cssVars({ "--tone": toneOf(scholar) })} onClick={(e) => openProfile(scholar.id, e.currentTarget)}>
    <i /><span><b>{scholar.name}</b><small>{data.faiths[scholar.faith]} · {data.fields[scholar.field]}</small></span>
    <ArrowRight size={14} aria-hidden="true" />
  </button>;
}

// The discoveries map card: the Holy Land & Sinai / Wider map switch, the two map stages (crossfading; their cameras are
// flown by MapStage through refs, never by re-rendering), the edge marker pointing to the find beyond the first map, and
// the year line from the first find to the last.
import { ArrowRight } from "lucide-react";
import type { RefObject } from "react";
import type { Find } from "@/data/teachers/pages-types";
import { cssVars, railPos, scholarById, VIEWS, type DiscoveryModel, type View } from "./model";
import type { MarkerSpec } from "./stage";

interface MapCardProps {
  model: DiscoveryModel;
  markers: Record<View, MarkerSpec[]>;
  mode: View;
  /** The chosen find, or null for all of them. */
  find: Find | null;
  stagesEl: RefObject<HTMLDivElement>;
  edgeRef: RefObject<HTMLButtonElement>;
  onSwitch: (view: View) => void;
  onFind: (find: Find) => void;
}

const MAP_NAMES: Record<View, string> = { holyland: "Holy Land & Sinai", med: "Wider map" };

export function MapCard({ model, markers, mode, find, stagesEl, edgeRef, onSwitch, onFind }: MapCardProps) {
  const edgeFind = model.edgeFind;
  return <figure className="dsc-mapcard">
    <LandDefs model={model} />
    <div className="dsc-tools">
      <div className="dsc-seg" role="group" aria-label="Map">
        {VIEWS.map((view) => <button key={view} type="button" aria-pressed={mode === view} onClick={() => onSwitch(view)}>{MAP_NAMES[view]}</button>)}
      </div>
      <p className="dsc-now" aria-live="polite">{find ? find.where[0] : `All ${model.finds.length} discoveries`}</p>
    </div>
    <div ref={stagesEl} className={`dsc-stages${find ? " dsc-has-active" : ""}`}>
      {VIEWS.map((view) => <Stage key={view} view={view} on={mode === view} markers={markers[view]} chosen={find?.id ?? null} onFind={onFind} model={model} />)}
      {edgeFind && <button ref={edgeRef} type="button" className="dsc-edge" hidden={mode !== "holyland"} onClick={() => onFind(edgeFind)}>
        <span className="dsc-edge-arrow"><ArrowRight size={15} aria-hidden="true" /></span>
        <span><b>{edgeFind.where[0]}</b><small>{scholarById(model.byId, edgeFind.by[0]).short} · {edgeFind.year}</small></span>
      </button>}
    </div>
    <Rail finds={model.finds} find={find} onFind={onFind} />
  </figure>;
}

/** The two land outlines, each one path whose holes (fill-rule evenodd) are the Dead Sea and the Sea of Galilee. */
function LandDefs({ model }: { model: DiscoveryModel }) {
  return <svg className="dsc-defs" aria-hidden="true"><defs>
    {VIEWS.map((view) => <path key={view} id={`tp-dsc-land-${view}`} d={model.data.views[view].land} fillRule="evenodd" vectorEffect="non-scaling-stroke" />)}
    <linearGradient id="tp-dsc-land-fill" x1="0" y1="0" x2=".5" y2="1"><stop className="dsc-stop-a" /><stop offset="1" className="dsc-stop-b" /></linearGradient>
  </defs></svg>;
}

interface StageProps { view: View; on: boolean; markers: MarkerSpec[]; chosen: string | null; model: DiscoveryModel; onFind: (find: Find) => void }

function Stage({ view, on, markers, chosen, model, onFind }: StageProps) {
  return <div className={`dsc-stage${on ? " dsc-on-stage" : ""}`} data-view={view}>
    <svg className="dsc-land" aria-hidden="true">
      <rect className="dsc-water" x="-4000" y="-4000" width="9000" height="9000" />
      <use href={`#tp-dsc-land-${view}`} className="dsc-landpath" />
    </svg>
    <div className="dsc-layer">
      {markers.map((m) => {
        const find = m.findId ? model.finds.find((f) => f.id === m.findId) : undefined;
        if (!find) return <div key={m.key} className="dsc-mk dsc-mk-sea dsc-center"><span className="dsc-lab">{m.name}</span></div>;
        const isOn = find.id === chosen;
        return <button key={m.key} type="button" className={`dsc-mk dsc-mk-find${isOn ? " dsc-on dsc-pulse" : ""}`} aria-label={`${find.name}, ${find.year}`} onClick={() => onFind(find)}>
          <i key={isOn ? "on" : "off"} className="dsc-mk-pulse" /><i className="dsc-mk-dot" />
          <span className="dsc-lab"><b>{find.name}</b><small>{find.year}</small></span>
        </button>;
      })}
    </div>
  </div>;
}

function Rail({ finds, find, onFind }: { finds: Find[]; find: Find | null; onFind: (find: Find) => void }) {
  const first = finds[0], last = finds[finds.length - 1], at = (year: number) => cssVars({ "--p": railPos(year).toFixed(2) });
  return <div className="dsc-rail" role="group" aria-label="The discoveries by year">
    <span className="dsc-rail-line" />
    {finds.map((f) => <button key={f.id} type="button" className={`dsc-rail-pt${f === find ? " dsc-on" : ""}`} style={at(f.year)} title={`${f.year} · ${f.name}`}
      aria-label={`${f.year}, ${f.name}`} onClick={() => onFind(f)}><i /></button>)}
    <span className="dsc-rail-end" style={at(first.year)}>{first.year}</span>
    <span className="dsc-rail-end" style={at(last.year)}>{last.year}</span>
    <span className={`dsc-rail-now${find ? " dsc-on" : ""}`} style={find ? at(find.year) : cssVars({ "--p": "0" })}>{find ? find.year : ""}</span>
  </div>;
}

import evidenceData from "../../../../../content/teachers/discovery-evidence.json";
// 03 · The discoveries: everything the section shows, derived from the Scholars data only (approved mock-up:
// design/scholars-directions/scholars/discoveries.js). The finds in date order, which lie on the Holy Land & Sinai map,
// and each find's "from the dig to your screen" thread: who found or studied it, what came of it, and where it reaches
// this site (or that it does not yet).
import type { CSSProperties } from "react";
import type { Field, Find, Scholar, ScholarsData } from "@/data/teachers/pages-types";

export type View = "holyland" | "med";
export const VIEWS: View[] = ["holyland", "med"];

const FIELD_TONE: Record<Field, string> = { history: "--gospels", texts: "--prophets", places: "--history", reference: "--epistles", theology: "--acts" };
/** Site areas a scholar's site note may name, and where each lives. */
export const AREA_ROUTE: Record<string, string> = {
  "Letters study": "/study/letters", Apologetics: "/apologetics", Topics: "/topics", "People pages": "/study/people", Rulers: "/study/rulers",
};
const WORDS = ["No", "One", "Two", "Three", "Four", "Five", "Six", "Seven"];

export const toneOf = (scholar: Scholar) => `var(${FIELD_TONE[scholar.field]})`;
export const word = (n: number) => WORDS[n] ?? String(n);
/** Custom properties for a style prop (React's CSSProperties has no index for "--name"). */
export const cssVars = (vars: Record<string, string>) => vars as CSSProperties;
/** The site area a scholar's site note names, if any. */
export const areaOf = (scholar: Scholar) => (scholar.site ? Object.keys(AREA_ROUTE).find((area) => scholar.site?.note.includes(area)) : undefined);

export type Step =
  | { kind: "who"; scholar: Scholar; role?:string }
  | { kind: "came"; work: [string, string|number]; url?:string }
  | { kind: "next"; scholar: Scholar; what: string }
  | { kind: "site"; scholar: Scholar; site: NonNullable<Scholar["site"]>; url?:string; label?:string }
  | { kind: "none" };
export interface Thread { steps: Step[]; reached: Scholar[]; people: Set<string> }

export interface DiscoveryModel {
  data: ScholarsData;
  byId: Record<string, Scholar>;
  /** The finds in date order. */
  finds: Find[];
  /** Ids of the finds on the Holy Land & Sinai map. */
  inHoly: Set<string>;
  /** The first find beyond that map (Ramsay's), marked on its edge. */
  edgeFind: Find | null;
  threads: Record<string, Thread>;
}

type Evidence = {year?:number;date:string;context:string;role:string;sources:{label:string;url:string}[];site?:{label:string;url:string;note:string;sourceTitle:string;sourceUrl:string}};
export const discoveryEvidence:Record<string,Evidence> = evidenceData.cases;
function threadOf(model: Pick<DiscoveryModel, "data" | "byId">, find: Find): Thread {
 const record=discoveryEvidence[find.id], steps:Step[]=[], reached:Scholar[]=[];
 for(const id of find.by)steps.push({kind:'who',scholar:scholarById(model.byId,id),role:record.role});
 steps.push({kind:'came',work:[record.sources[0].label,record.date],url:record.sources[0].url});
 if(record.site){
  const scholar=scholarById(model.byId,find.id==='sinaiticus'?'westcott':find.by[0]);
  if(find.id==='sinaiticus')steps.push({kind:'next',scholar,what:'Cited discussion of the manuscript; not a claim that this edition supplies the site text.'});
  steps.push({kind:'came',work:[record.site.sourceTitle,''],url:record.site.sourceUrl});
  reached.push(scholar);steps.push({kind:'site',scholar,site:{status:'in-use',note:record.site.note},url:record.site.url,label:record.site.label});
 }else steps.push({kind:'none'});
 return {steps,reached,people:new Set(steps.flatMap(st=>'scholar' in st?[st.scholar.id]:[]))};
}

export function scholarById(byId: Record<string, Scholar>, id: string): Scholar {
  const scholar = byId[id];
  if (!scholar) throw new Error(`Discoveries: no scholar with id "${id}" in the Scholars data (named by a find or the chain of the text)`);
  return scholar;
}

export function buildModel(data: ScholarsData): DiscoveryModel {
  const byId = Object.fromEntries(data.scholars.map((s) => [s.id, s]));
  const finds = data.finds.map(f=>({...f,year:discoveryEvidence[f.id].year??f.year,line:discoveryEvidence[f.id].context})).sort((a,b)=>a.year-b.year);
  if (!finds.length) throw new Error("Discoveries: the Scholars data lists no finds");
  const inHoly = new Set(finds.filter((f) => data.views.holyland.points[`find:${f.id}`]).map((f) => f.id));
  const threads = Object.fromEntries(finds.map((f) => [f.id, threadOf({ data, byId }, f)]));
  return { data, byId, finds, inHoly, edgeFind: finds.find((f) => !inHoly.has(f.id)) ?? null, threads };
}

export interface Overview { span: string; title: string; from: string; lie: string; reach: string }

/** The "All 7" card's words, computed from the finds and their threads. */
export function overviewOf(model: DiscoveryModel): Overview {
  const { finds, byId, threads, inHoly } = model;
  const first = finds[0], last = finds[finds.length - 1];
  const outside = finds.filter((f) => !inHoly.has(f.id));
  const reach = finds.filter((f) => threads[f.id].reached.length);
  const through = reach.map((f) => `${f.name}, through ${threads[f.id].reached.map((s) => s.short).join(" and ")}`).join("; ");
  const areas = [...new Set(reach.map((f) => discoveryEvidence[f.id].site?.label ?? "this site"))];
  const beyond = outside.map((f) => `${scholarById(byId, f.by[0]).short}'s lies beyond this map, at ${f.where[0]}`).join("; ");
  return {
    span: `${first.year}–${last.year}`,
    title: `The ${word(finds.length).toLowerCase()} discoveries`,
    from: `From ${scholarById(byId, first.by[0]).name} at ${first.where[0]} in ${first.year} to ${scholarById(byId, last.by[0]).name} at ${last.where[0]} in ${last.year}.`,
    lie: `${word(finds.length - outside.length)} lie in the Holy Land and Sinai${beyond ? `; ${beyond}` : ""}.`,
    reach: reach.length
      ? `${word(reach.length)} reach this site's ${areas.join(" and ")}: ${through}. The other ${word(finds.length - reach.length).toLowerCase()} have no verified feature connection in this review.`
      : "No feature connections verified in this review.",
  };
}

/** Where a year sits on the year line, 0–100. */
export const railPos = (year: number) => ((year - 1830) / (1970 - 1830)) * 100;

// The discoveries map's geometry (ported from the mock-up's direction C map). Each pre-projected view is Mercator; two
// known finds give the projection, so the sea labels and the off-map marker sit in the same coordinates as the data.
import type { Point, ScholarsData } from "@/data/teachers/pages-types";
import type { View } from "./model";

export interface Cam { x: number; y: number; w: number }
export interface Projection { project: (lon: number, lat: number) => Point; invert: (x: number, y: number) => Point }

const mercY = (lat: number) => Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));

/** a and b are [lon, lat, x, y] of two known places. */
function mercatorFrom(a: number[], b: number[]): Projection {
  const A = (b[2] - a[2]) / (b[0] - a[0]), B = a[2] - A * a[0];
  const C = (b[3] - a[3]) / (mercY(b[1]) - mercY(a[1])), D = a[3] - C * mercY(a[1]);
  return {
    project: (lon, lat) => [A * lon + B, C * mercY(lat) + D],
    invert: (x, y) => [(x - B) / A, ((2 * Math.atan(Math.exp((y - D) / C)) - Math.PI / 2) * 180) / Math.PI],
  };
}

export function buildProjections(data: ScholarsData): Record<View, Projection> {
  const fromFind = (view: View, id: string) => {
    const find = data.finds.find((f) => f.id === id), p = data.views[view].points[`find:${id}`];
    if (!find || !p) throw new Error(`Discoveries map: the find "${id}" is needed to place the ${view} map, but it is missing from the data`);
    return [find.where[2], find.where[1], p[0], p[1]];
  };
  const from = (view: View) => mercatorFrom(fromFind(view, "sinaiticus"), fromFind(view, "hazor"));
  return { holyland: from("holyland"), med: from("med") };
}

/** [label, lon, lat]; the Dead Sea and the Sea of Galilee are holes in the land outline. */
export const WATERS: Record<View, [string, number, number][]> = {
  holyland: [["Mediterranean Sea", 33.55, 32.35], ["Sinai", 33.75, 29.75], ["Dead Sea", 35.5, 31.5], ["Sea of Galilee", 35.59, 32.83]],
  med: [["Mediterranean Sea", 18.5, 35.2], ["Asia Minor", 33, 39.3], ["Black Sea", 34.5, 43.2]],
};

/** Move a camera from one view's coordinates to the other's through longitude and latitude. */
export function convertCam(projections: Record<View, Projection>, from: View, to: View, cam: Cam): Cam {
  const P = projections[from], Q = projections[to];
  const [lonA, latA] = P.invert(cam.x - cam.w / 2, cam.y), [lonB] = P.invert(cam.x + cam.w / 2, cam.y);
  const [lon, lat] = P.invert(cam.x, cam.y), [x, y] = Q.project(lon, lat);
  return { x, y, w: Math.abs(Q.project(lonB, latA)[0] - Q.project(lonA, latA)[0]) };
}

export interface Zoom { at: (t: number) => [number, number, number]; duration: number }

/** d3's smooth zoom (van Wijk and Nuij): pans out a little on long moves so the eye keeps its place. */
export function interpolateZoom([ux0, uy0, w0]: number[], [ux1, uy1, w1]: number[]): Zoom {
  const rho = Math.SQRT2, dx = ux1 - ux0, dy = uy1 - uy0, d2 = dx * dx + dy * dy;
  if (d2 < 1e-12) {
    const S0 = Math.log(w1 / w0) / rho;
    return { at: (t) => [ux0 + t * dx, uy0 + t * dy, w0 * Math.exp(rho * t * S0)], duration: Math.abs(S0) * 1000 };
  }
  const d1 = Math.sqrt(d2), b0 = (w1 * w1 - w0 * w0 + 4 * d2) / (2 * w0 * 2 * d1), b1 = (w1 * w1 - w0 * w0 - 4 * d2) / (2 * w1 * 2 * d1);
  const r0 = Math.log(Math.sqrt(b0 * b0 + 1) - b0), r1 = Math.log(Math.sqrt(b1 * b1 + 1) - b1), S1 = (r1 - r0) / rho;
  const at = (t: number): [number, number, number] => {
    const s = t * S1, c0 = Math.cosh(r0), u = (w0 / (2 * d1)) * (c0 * Math.tanh(rho * s + r0) - Math.sinh(r0));
    return [ux0 + u * dx, uy0 + u * dy, (w0 * c0) / Math.cosh(rho * s + r0)];
  };
  return { at, duration: S1 * 1000 };
}

export const ease = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
export const reducedMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;

// A map whose land is an SVG (its viewBox is the camera, animated in requestAnimationFrame) with markers and labels in
// an HTML layer above it, moved by transforms only. React draws the elements once; this class only moves them, through
// refs: the svg's viewBox, each marker's transform, and two data attributes (data-side, data-off) React never sets.
import type { DiscoveryModel, View } from "./model";
import { ease, interpolateZoom, reducedMotion, WATERS, type Cam, type Projection } from "./projection";

/** One marker as React draws it: a find (a button with a dot and a label) or a sea's name. */
export interface MarkerSpec { key: string; x: number; y: number; findId: string | null; name: string; year: number | null; labelLeft: boolean }

export function markersFor(model: DiscoveryModel, projections: Record<View, Projection>, view: View): MarkerSpec[] {
  const points = model.data.views[view].points, specs: MarkerSpec[] = [];
  for (const f of model.finds) {
    const p = points[`find:${f.id}`];
    if (p) specs.push({ key: f.id, x: p[0], y: p[1], findId: f.id, name: f.name, year: f.year, labelLeft: f.id === "robinsons-arch" || f.id === "hazor" });
  }
  for (const [name, lon, lat] of WATERS[view]) {
    const [x, y] = projections[view].project(lon, lat);
    specs.push({ key: `sea:${name}`, x, y, findId: null, name, year: null, labelLeft: false });
  }
  return specs;
}

interface Marker extends MarkerSpec { el: HTMLElement; label: HTMLElement | null; center: boolean; sx: number; sy: number; lw: number; lh: number; priority: number; force: boolean }
type Box = [number, number, number, number];

export class MapStage {
  cam: Cam;
  cw = 1;
  ch = 1;
  onRender: ((stage: MapStage) => void) | null = null;
  private markers: Marker[];
  private svg: SVGSVGElement;
  private raf = 0;
  private observer: ResizeObserver;
  private width: number;
  private height: number;

  constructor(readonly el: HTMLElement, view: { width: number; height: number }, specs: MarkerSpec[], private minW: number, private margin = 12) {
    const svg = el.querySelector("svg"), layer = el.querySelector(".dsc-layer");
    if (!svg || !layer || layer.children.length !== specs.length) throw new Error(`Discoveries map: the stage has ${layer?.children.length ?? 0} marker elements, expected ${specs.length}`);
    this.svg = svg; this.width = view.width; this.height = view.height;
    this.cam = { x: view.width / 2, y: view.height / 2, w: view.width };
    this.markers = specs.map((spec, i) => {
      const markerEl = layer.children[i] as HTMLElement, center = spec.findId === null;
      if (!center && spec.labelLeft) markerEl.dataset.side = "left";
      return { ...spec, el: markerEl, label: markerEl.querySelector<HTMLElement>(".dsc-lab"), center, sx: 0, sy: 0, lw: 0, lh: 0, priority: center ? 1 : 10, force: false };
    });
    this.size();
    this.observer = new ResizeObserver(() => { this.size(); this.cam = this.clamp(this.cam); this.render(); });
    this.observer.observe(el);
  }
  destroy() { cancelAnimationFrame(this.raf); this.observer.disconnect(); this.onRender = null; }
  private size() { this.cw = this.el.clientWidth || 1; this.ch = this.el.clientHeight || 1; }
  clamp({ x, y, w }: Cam): Cam {
    const m = this.margin, W = this.width, H = this.height, a = this.ch / this.cw;
    w = Math.max(this.minW, Math.min(w, W + 2 * m, (H + 2 * m) / a));
    const h = w * a;
    x = Math.min(Math.max(x, -m + w / 2), W + m - w / 2);
    y = Math.min(Math.max(y, -m + h / 2), H + m - h / 2);
    return { x, y, w };
  }
  /** The camera that holds these points with `pad` screen pixels to spare on every side. */
  fit(points: number[][], pad = 48, minW = this.minW): Cam {
    const xs = points.map((p) => p[0]), ys = points.map((p) => p[1]);
    const bw = Math.max(...xs) - Math.min(...xs), bh = Math.max(...ys) - Math.min(...ys);
    const px = Math.min(pad, this.cw / 4), py = Math.min(pad, this.ch / 4);
    const w = Math.max(minW, (bw * this.cw) / (this.cw - 2 * px), (bh * this.cw) / (this.ch - 2 * py));
    return this.clamp({ x: (Math.max(...xs) + Math.min(...xs)) / 2, y: (Math.max(...ys) + Math.min(...ys)) / 2, w });
  }
  toScreen(x: number, y: number): [number, number] {
    const s = this.cw / this.cam.w, h = this.cam.w * (this.ch / this.cw);
    return [(x - (this.cam.x - this.cam.w / 2)) * s, (y - (this.cam.y - h / 2)) * s];
  }
  /** The chosen find's label is larger and always shown; the others give way to it. */
  setActive(findId: string | null) {
    for (const m of this.markers) {
      if (m.center) continue;
      const on = m.findId === findId;
      m.priority = on ? 20 : 10;
      if (on !== m.force) m.lw = 0; // the chosen label is larger: measure it again
      m.force = on;
    }
  }
  jump(cam: Cam) { cancelAnimationFrame(this.raf); this.cam = this.clamp(cam); this.render(); }
  fly(target: Cam, max = 1500) {
    cancelAnimationFrame(this.raf);
    target = this.clamp(target);
    const still = Math.abs(target.x - this.cam.x) + Math.abs(target.y - this.cam.y) + Math.abs(target.w - this.cam.w) < 0.5;
    if (still || reducedMotion()) { this.jump(target); return; }
    const zoom = interpolateZoom([this.cam.x, this.cam.y, this.cam.w], [target.x, target.y, target.w]);
    const duration = Math.min(max, Math.max(650, zoom.duration * 0.9)), start = performance.now();
    const step = (now: number) => {
      const t = Math.min(1, (now - start) / duration), [x, y, w] = zoom.at(ease(t));
      this.cam = t < 1 ? { x, y, w } : target;
      this.render();
      if (t < 1) this.raf = requestAnimationFrame(step);
    };
    this.raf = requestAnimationFrame(step);
  }
  render() {
    const { x, y, w } = this.cam, h = w * (this.ch / this.cw);
    this.svg.setAttribute("viewBox", `${(x - w / 2).toFixed(2)} ${(y - h / 2).toFixed(2)} ${w.toFixed(2)} ${h.toFixed(2)}`);
    for (const m of this.markers) {
      [m.sx, m.sy] = this.toScreen(m.x, m.y);
      m.el.style.transform = `translate3d(${m.sx.toFixed(1)}px, ${m.sy.toFixed(1)}px, 0)`;
    }
    this.placeLabels();
    this.onRender?.(this);
  }
  /** Every dot is an obstacle a label may not cover; labels go highest priority first, and one that would overlap a label
   *  already shown, or leave the map, is hidden. The chosen place always keeps its name. */
  private placeLabels() {
    const placed: Box[] = this.markers.filter((m) => !m.center).map((m) => [m.sx - 6, m.sy - 6, m.sx + 6, m.sy + 6]);
    for (const m of [...this.markers].sort((a, b) => b.priority - a.priority)) {
      if (!m.label) continue;
      if (!m.lw) { m.lw = m.label.offsetWidth; m.lh = m.label.offsetHeight; }
      const sides = m.center ? ["center"] : m.labelLeft ? ["left", "right"] : ["right", "left"];
      let shown: string | null = null;
      for (const side of sides) {
        const box = this.labelBox(m, side);
        const out = box[0] < 2 || box[2] > this.cw - 2 || box[1] < 2 || box[3] > this.ch - 2;
        if (out || placed.some((o) => box[0] < o[2] && box[2] > o[0] && box[1] < o[3] && box[3] > o[1])) continue;
        shown = side; placed.push(box); break;
      }
      if (!shown && m.force) shown = sides[0];
      m.label.toggleAttribute("data-off", !shown);
      if (shown && !m.center) m.el.dataset.side = shown;
    }
  }
  private labelBox(m: Marker, side: string): Box {
    const left = side === "center" ? m.sx - m.lw / 2 : side === "left" ? m.sx - 10 - m.lw : m.sx + 10;
    return [left - 2, m.sy - m.lh / 2 - 1, left + m.lw + 2, m.sy + m.lh / 2 + 1];
  }
}

/** The off-map marker sits on the map's edge, on the line from the centre towards the place, its arrow pointing there. */
export function placeEdge(stage: MapStage, edge: HTMLElement, target: [number, number]) {
  const [sx, sy] = stage.toScreen(target[0], target[1]);
  const cx = stage.cw / 2, cy = stage.ch / 2, dx = sx - cx, dy = sy - cy, ew = edge.offsetWidth / 2 + 14, eh = edge.offsetHeight / 2 + 14;
  const k = Math.min((cx - ew) / Math.abs(dx || 1e-6), (cy - eh) / Math.abs(dy || 1e-6));
  edge.style.transform = `translate3d(${(cx + dx * k - edge.offsetWidth / 2).toFixed(1)}px, ${(cy + dy * k - edge.offsetHeight / 2).toFixed(1)}px, 0)`;
  const arrow = edge.querySelector<HTMLElement>(".dsc-edge-arrow");
  if (arrow) arrow.style.transform = `rotate(${Math.atan2(dy, dx)}rad)`;
}

// The discoveries section's moving parts, kept out of React's render: the two map stages (Holy Land & Sinai, and the
// wider map) flying their cameras in requestAnimationFrame, the crossfade between them, and the list that chooses the
// card under its reading line as it is scrolled. React re-renders only when the chosen find or the map changes.
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import type { Find } from "@/data/teachers/pages-types";
import { VIEWS, type DiscoveryModel, type View } from "./model";
import { convertCam, reducedMotion, type Cam, type Projection } from "./projection";
import { MapStage, placeEdge, type MarkerSpec } from "./stage";

const overviewCam = (stage: MapStage, model: DiscoveryModel, view: View): Cam => {
  const points = model.finds.map((f) => model.data.views[view].points[`find:${f.id}`]).filter(Boolean);
  return stage.fit(points, 40, view === "med" ? 300 : 90);
};
/** Sit the chosen place a little left of centre so its name, to the right, has room. */
const findCam = (model: DiscoveryModel, find: Find, view: View): Cam => {
  const p = model.data.views[view].points[`find:${find.id}`], w = view === "med" ? 300 : find.id === "sinaiticus" ? 420 : 250;
  return { x: p[0] + w * 0.14, y: p[1], w };
};
export const viewOf = (model: DiscoveryModel, find: Find): View => (model.inHoly.has(find.id) ? "holyland" : "med");

export function useDiscoveryMap(model: DiscoveryModel, projections: Record<View, Projection>, markers: Record<View, MarkerSpec[]>) {
  const stagesEl = useRef<HTMLDivElement>(null), edgeRef = useRef<HTMLButtonElement>(null);
  const stages = useRef<Record<View, MapStage> | null>(null);
  const modeRef = useRef<View>("holyland");
  const [mode, setMode] = useState<View>("holyland");

  useLayoutEffect(() => {
    const host = stagesEl.current;
    if (!host) return;
    const make = (view: View) => {
      const el = host.querySelector<HTMLElement>(`.dsc-stage[data-view="${view}"]`);
      if (!el) throw new Error(`Discoveries map: the ${view} stage was not drawn`);
      return new MapStage(el, model.data.views[view], markers[view], view === "med" ? 120 : 90);
    };
    const made: Record<View, MapStage> = { holyland: make("holyland"), med: make("med") };
    const edgeFind = model.edgeFind;
    if (edgeFind) {
      const target = projections.holyland.project(edgeFind.where[2], edgeFind.where[1]);
      made.holyland.onRender = (stage) => { if (edgeRef.current && modeRef.current === "holyland") placeEdge(stage, edgeRef.current, target); };
    }
    for (const view of VIEWS) made[view].jump(overviewCam(made[view], model, view));
    stages.current = made;
    return () => { for (const view of VIEWS) made[view].destroy(); stages.current = null; };
  }, [model, projections, markers]);

  // The edge marker is shown again when the Holy Land map returns: place it once it is visible.
  useLayoutEffect(() => { stages.current?.holyland.render(); }, [mode]);

  const goTo = useCallback((next: View, camFor: (stage: MapStage) => Cam) => {
    const all = stages.current;
    if (!all) return;
    if (next !== modeRef.current) {
      all[next].jump(convertCam(projections, modeRef.current, next, all[modeRef.current].cam));
      modeRef.current = next;
      setMode(next);
    }
    all[next].fly(camFor(all[next]));
  }, [projections]);

  /** Fly to a find (on whichever map holds it), or back to all of them. */
  const show = useCallback((find: Find | null) => {
    for (const view of VIEWS) stages.current?.[view].setActive(find?.id ?? null);
    if (!find) goTo("holyland", (stage) => overviewCam(stage, model, "holyland"));
    else { const view = viewOf(model, find); goTo(view, () => findCam(model, find, view)); }
  }, [goTo, model]);

  const switchMap = useCallback((view: View) => {
    if (view !== modeRef.current) goTo(view, (stage) => overviewCam(stage, model, view));
  }, [goTo, model]);

  return { stagesEl, edgeRef, mode, show, switchMap };
}

/** The finds list: scrolling it makes the card under the reading line (a third of the way down, or the middle across on a
 *  phone) the chosen one; choosing a card scrolls it into place. A spacer after the last card lets it reach that line. */
export function useListFollow(onPick: (index: number) => void) {
  const listRef = useRef<HTMLDivElement>(null), endRef = useRef<HTMLDivElement>(null), programmatic = useRef(Number.NEGATIVE_INFINITY);
  const pickRef = useRef(onPick);
  useLayoutEffect(() => { pickRef.current = onPick; }, [onPick]);

  useEffect(() => {
    const list = listRef.current, end = endRef.current;
    if (!list || !end) return;
    const cards = () => [...list.querySelectorAll<HTMLElement>(".dsc-find")];
    const horizontal = () => getComputedStyle(list).flexDirection === "row";
    let pending = false, frame = 0;
    const onScroll = () => {
      if (pending || performance.now() - programmatic.current < 900) return;
      pending = true;
      frame = requestAnimationFrame(() => {
        pending = false;
        const h = horizontal(), line = h ? list.scrollLeft + list.clientWidth / 2 : list.scrollTop + Math.min(140, list.clientHeight * 0.3);
        let best = 0;
        cards().forEach((card, n) => { if ((h ? card.offsetLeft : card.offsetTop) <= line) best = n; });
        pickRef.current(best);
      });
    };
    const fitEnd = () => {
      const last = cards().at(-1);
      end.style.height = horizontal() || !last ? "" : `${Math.max(0, list.clientHeight - last.offsetHeight - 40)}px`;
    };
    const observer = new ResizeObserver(fitEnd);
    observer.observe(list);
    list.addEventListener("scroll", onScroll, { passive: true });
    return () => { list.removeEventListener("scroll", onScroll); observer.disconnect(); cancelAnimationFrame(frame); };
  }, []);

  const scrollToCard = useCallback((index: number) => {
    const list = listRef.current, card = list?.querySelectorAll<HTMLElement>(".dsc-find")[index];
    if (!list || !card) return;
    programmatic.current = performance.now();
    const behavior: ScrollBehavior = reducedMotion() ? "auto" : "smooth";
    if (getComputedStyle(list).flexDirection === "row") list.scrollTo({ left: card.offsetLeft - list.clientWidth / 2 + card.offsetWidth / 2, behavior });
    else list.scrollTo({ top: card.offsetTop - 14, behavior });
  }, []);

  return { listRef, endRef, scrollToCard };
}

