// The landing's search box: a combobox that lists matching scholars (arrow keys move, Enter opens the profile, Esc
// clears). The query lives in the landing, which also lights the matches in the constellation.
import { useEffect, useRef, useState, type KeyboardEvent } from "react";
import { ArrowRight, Search } from "lucide-react";
import { years } from "../marks/facts";
import { Mark } from "../marks/Mark";
import { toneStyle } from "../marks/shapes";
import type { Match } from "./search";

interface FinderProps { query: string; onQuery: (q: string) => void; found: Match[]; onOpen: (id: string, origin: Element | null) => void }
const optionId = (i: number) => `sc-lnd-opt-${i}`;

export function Finder({ query, onQuery, found, onOpen }: FinderProps) {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const box = useRef<HTMLDivElement>(null), list = useRef<HTMLDivElement>(null);
  const q = query.trim(), shown = open && q.length > 0;
  useEffect(() => {
    const away = (event: globalThis.PointerEvent) => { if (!(event.target instanceof Node && box.current?.contains(event.target))) setOpen(false); };
    document.addEventListener("pointerdown", away);
    return () => document.removeEventListener("pointerdown", away);
  }, []);
  const choose = (i: number) => {
    const m = found[i];
    if (!m) return;
    setOpen(false);
    onOpen(m.s.id, list.current?.querySelectorAll(".lnd-opt")[i] ?? null);
  };
  const move = (by: number) => {
    if (!found.length) return;
    const next = (active + by + found.length) % found.length;
    setActive(next);
    list.current?.querySelectorAll(".lnd-opt")[next]?.scrollIntoView({ block: "nearest" });
  };
  const onKey = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "ArrowDown") { event.preventDefault(); move(1); }
    else if (event.key === "ArrowUp") { event.preventDefault(); move(-1); }
    else if (event.key === "Enter" && found.length) { event.preventDefault(); choose(Math.max(0, active)); }
    else if (event.key === "Escape") { onQuery(""); setOpen(false); }
  };
  return <div className="lnd-find" ref={box}>
    <label className="lnd-search"><Search size={18} aria-hidden="true" />
      <input type="search" placeholder="Find a scholar, a book or a field" autoComplete="off" spellCheck={false} value={query}
        role="combobox" aria-expanded={shown} aria-controls="sc-lnd-results" aria-autocomplete="list" aria-label="Find a scholar, a book or a field"
        aria-activedescendant={shown && found.length ? optionId(active) : undefined}
        onChange={(e) => { onQuery(e.target.value); setActive(0); setOpen(true); }} onFocus={() => setOpen(true)} onKeyDown={onKey} /></label>
    <div className="lnd-results" id="sc-lnd-results" role="listbox" aria-label="Matching scholars" hidden={!shown} ref={list}>
      {found.length ? <>
        {found.map((m, i) => <button key={m.s.id} type="button" role="option" id={optionId(i)} className="lnd-opt" aria-selected={i === active}
          style={toneStyle(m.s.field)} onClick={() => choose(i)}>
          <Mark scholar={m.s} size={34} className="lnd-mark" />
          <span className="lnd-opt-t"><b>{m.s.name}</b><small>{years(m.s)} · {"work" in m.why ? <><i>{m.why.work}</i>, {m.why.year}</> : m.why.text}</small></span>
          <span className="lnd-opt-go"><ArrowRight size={14} aria-hidden="true" /></span></button>)}
        <p className="lnd-res-n">{found.length} {found.length === 1 ? "match" : "matches"}</p>
      </> : <p className="lnd-none">Nothing matches “{q}”. Try a name like Jerome, a book like the Vulgate, or a field like archaeology.</p>}
    </div>
  </div>;
}

src/pages/teachers/scholars/landing/layo:
// The landing's constellation: where each of the scholars' marks sits. Two compositions: a wide one beside the copy,
// and a tall one for phones. Each field gathers round its own centre; its scholars start on a small spiral in order of
// birth (so the line through them reads as a gentle curl), then a few hundred rounds of gentle pushing keep marks from
// touching (deterministic, done once per layout). Finally the picture is cropped to its own bounds so it fills the stage.
import type { Field, Scholar, ScholarsData } from "@/data/teachers/pages-types";
export type SkyPerson = Pick<Scholar, "id" | "name" | "field" | "site"> & { born?: number; work?: string; records?: number };
export interface SkyData { fields: ScholarsData["fields"]; scholars: SkyPerson[] }
const byBirth = (people: SkyPerson[]) => [...people].sort((a,b)=>(a.born ?? Infinity)-(b.born ?? Infinity));

export type LayoutName = "wide" | "tall";
interface LayoutSpec { size: number; gap: number; centres: Record<Field, [number, number]> }
const LAYOUTS: Record<LayoutName, LayoutSpec> = {
  wide: { size: 58, gap: 76, centres: { texts: [190, 250], history: [470, 150], theology: [720, 170], reference: [630, 450], places: [325, 540] } },
  tall: { size: 50, gap: 58, centres: { texts: [118, 215], history: [300, 140], theology: [318, 352], reference: [268, 560], places: [100, 560] } },
};

export interface SkyNode { s: SkyPerson; x: number; y: number; hx: number; hy: number }
export interface SkyField { field: Field; own: SkyNode[]; mx: number; my: number; bottom: number; r: number }
export interface Sky { name: LayoutName; w: number; h: number; size: number; nodes: SkyNode[]; fields: SkyField[] }

function seed(data: SkyData, spec: LayoutSpec): SkyNode[] {
  const nodes: SkyNode[] = [], born = byBirth(data.scholars);
  for (const field of Object.keys(data.fields) as Field[]) {
    const [cx, cy] = spec.centres[field], b = spec.gap / (2 * Math.PI);
    let theta = Math.PI * 1.25;
    born.filter((s) => s.field === field).forEach((s, i) => {
      const r = i ? b * theta : 0, a = theta + cx * 0.013;
      const x = cx + r * Math.cos(a), y = cy + r * Math.sin(a);
      nodes.push({ s, hx: x, hy: y, x, y });
      if (i) theta += spec.gap / Math.max(r, spec.gap * 0.7);
    });
  }
  return nodes;
}

function relax(nodes: SkyNode[], gap: number) {
  for (let round = 0; round < 300; round++) {
    for (const n of nodes) { n.x += (n.hx - n.x) * 0.03; n.y += (n.hy - n.y) * 0.03; }
    for (let i = 0; i < nodes.length; i++) for (let j = i + 1; j < nodes.length; j++) {
      const a = nodes[i], b = nodes[j], min = a.s.field === b.s.field ? gap : gap + 30;
      let dx = b.x - a.x, dy = b.y - a.y, d = Math.hypot(dx, dy);
      if (d >= min) continue;
      if (d < 0.01) { dx = 1; dy = 0; d = 1; }
      const push = (min - d) / 2;
      a.x -= dx / d * push; a.y -= dy / d * push; b.x += dx / d * push; b.y += dy / d * push;
    }
  }
}

function groups(data: SkyData, nodes: SkyNode[], size: number): SkyField[] {
  return (Object.keys(data.fields) as Field[]).map((field) => {
    const own = nodes.filter((n) => n.s.field === field);
    const mx = own.reduce((a, n) => a + n.x, 0) / own.length, my = own.reduce((a, n) => a + n.y, 0) / own.length;
    return { field, own, mx, my, bottom: Math.max(...own.map((n) => n.y)), r: Math.max(...own.map((n) => Math.hypot(n.x - mx, n.y - my))) + size };
  }).filter((f) => f.own.length > 0);
}

export function buildSky(data: SkyData, name: LayoutName): Sky {
  const spec = LAYOUTS[name], nodes = seed(data, spec);
  relax(nodes, spec.gap);
  const pad = 26, half = spec.size / 2 + 6, labelRoom = 40;
  const minX = Math.min(...nodes.map((n) => n.x)) - half - pad, maxX = Math.max(...nodes.map((n) => n.x)) + half + pad;
  const minY = Math.min(...nodes.map((n) => n.y)) - half - pad, maxY = Math.max(...nodes.map((n) => n.y)) + half + labelRoom;
  for (const n of nodes) { n.x -= minX; n.y -= minY; }
  return { name, w: Math.round(maxX - minX), h: Math.round(maxY - minY), size: spec.size, nodes, fields: groups(data, nodes, spec.size) };
}

/** Each mark's own slow drift loop (offsets, duration, phase), varied by its place in the list. */
export const driftStyle = (i: number) => ({
  "--fx": `${((i * 37) % 7 - 3) * 0.9}px`, "--fy": `${((i * 53) % 7 - 3) * 0.9}px`, "--dur": `${9 + (i * 13) % 7}s`, "--fd": `-${(i * 1.7) % 9}s`,
});

src/pages/teachers/scholars/landing/sear:
// The landing's search: scholars by name, book, field, faith or place. Every word must appear somewhere; names rank
// first, then works, then field, place or faith. Each match says why it matched when it was not the name.
import type { Field, Scholar, ScholarsData } from "@/data/teachers/pages-types";
import { byBirth } from "../marks/facts";

const FIELD_WORDS: Record<Field, string> = {
  history: "historian", texts: "translator languages greek hebrew latin", places: "archaeologist archaeology dig",
  reference: "dictionary concordance", theology: "theologian philosopher",
};
export type Why = { work: string; year: number } | { text: string };
export interface Match { s: Scholar; score: number; why: Why }

function score(data: ScholarsData, s: Scholar, words: string[]): Omit<Match, "s"> | null {
  const name = `${s.name} ${s.short}`.toLowerCase(), works = s.works.map((w) => w[0].toLowerCase());
  const field = `${data.fields[s.field]} ${FIELD_WORDS[s.field]}`.toLowerCase(), place = s.place[0].toLowerCase();
  const faith = data.faiths[s.faith].toLowerCase();
  const all = [name, ...works, field, place, faith].join(" ");
  if (!words.every((w) => all.includes(w))) return null;
  if (words.every((w) => name.includes(w))) {
    return { score: name.split(/\s+/).some((part) => part.startsWith(words[0])) ? 4 : 3, why: { text: data.fields[s.field] } };
  }
  const work = s.works.find(([t]) => words.some((w) => t.toLowerCase().includes(w)));
  if (work) return { score: 2, why: { work: work[0], year: work[1] } };
  if (words.some((w) => field.includes(w))) return { score: 1, why: { text: data.fields[s.field] } };
  if (words.some((w) => place.includes(w))) return { score: 1, why: { text: `Worked in ${s.place[0]}` } };
  return { score: 1, why: { text: data.faiths[s.faith] } };
}

export function findScholars(data: ScholarsData, query: string): Match[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return [];
  const out: Match[] = [];
  for (const s of byBirth(data.scholars)) {
    const hit = score(data, s, words);
    if (hit) out.push({ s, ...hit });
  }
  return out.sort((a, b) => b.score - a.score || a.s.born - b.s.born);
}

