// The profile's motion: the panel grows out of the element that opened it and shrinks back into it (Web Animations on
// transform and opacity only), and the page scroll is locked while it is open.
const EASE = "cubic-bezier(.16, 1, .3, 1)";

const isCard = (el: Element | null) => Boolean(el?.classList.contains("cat-card"));

/** A catalogue card hides while the panel stands in for it; any other origin stays where it is. */
export function liftCard(el: Element | null, on: boolean) {
  if (isCard(el)) el?.classList.toggle("prf-lifted", on);
}

const towards = (from: DOMRect, to: DOMRect) =>
  `translate(${from.left - to.left}px, ${from.top - to.top}px) scale(${from.width / to.width}, ${from.height / to.height})`;

export function grow(panel: HTMLElement, body: HTMLElement, origin: Element | null) {
  const end = panel.getBoundingClientRect(), start = origin?.isConnected ? origin.getBoundingClientRect() : null;
  if (start && start.width) {
    liftCard(origin, true);
    panel.animate([{ transform: towards(start, end), borderRadius: "28px", opacity: isCard(origin) ? 1 : 0.2 }, { transform: "none", opacity: 1 }], { duration: 520, easing: EASE });
  } else {
    panel.animate([{ transform: "translateY(24px) scale(.97)", opacity: 0 }, { transform: "none", opacity: 1 }], { duration: 420, easing: EASE });
  }
  body.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 300, delay: 160, easing: "ease-out", fill: "backwards" });
}

/** Shrink back into the origin if it is still on screen, else sink and fade; `done` runs at the end. Returns a cancel. */
export function shrink(panel: HTMLElement, body: HTMLElement, origin: Element | null, done: () => void): () => void {
  const target = origin && origin.isConnected && !(origin instanceof HTMLElement && origin.hidden) ? origin.getBoundingClientRect() : null;
  const end = panel.getBoundingClientRect();
  const onScreen = Boolean(target && target.width && target.bottom > 0 && target.top < innerHeight);
  const frames = onScreen && target
    ? [{ transform: "none" }, { transform: towards(target, end), borderRadius: "28px", opacity: 0.4 }]
    : [{ transform: "none", opacity: 1 }, { transform: "translateY(18px) scale(.97)", opacity: 0 }];
  const fade = body.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 140, fill: "forwards" });
  const move = panel.animate(frames, { duration: onScreen ? 380 : 260, easing: onScreen ? EASE : "ease-in" });
  move.onfinish = () => { fade.cancel(); done(); };
  return () => { move.onfinish = null; move.cancel(); fade.cancel(); };
}

/** Stop the page scrolling behind the profile (keeping the scrollbar's room); returns the undo. */
export function lockPage(): () => void {
  const root = document.documentElement.style, was = { overflow: root.overflow, gutter: root.scrollbarGutter };
  root.overflow = "hidden";
  root.scrollbarGutter = "stable";
  return () => { root.overflow = was.overflow; root.scrollbarGutter = was.gutter; };
}

src/pages/teachers/scholars/profile/Prof:
// The profile's small map: the Mediterranean world when the scholar worked there, otherwise the whole world. The land is
// one even-odd path (lakes and inland seas stay open); faint dots are the other scholars, a pulsing halo marks this one,
// diamonds mark their finds. Stepping to another scholar on the same map glides the view box there (rAF, attribute only).
import { memo, useLayoutEffect, useRef } from "react";
import type { Scholar, ScholarsData } from "@/data/teachers/pages-types";
import { reducedMotion } from "../marks/dom";
import { toneStyle } from "../marks/shapes";

type MapName = "med" | "world";
type Box = [number, number, number, number];

/** The land and the other scholars' dots: large and unchanging per map, so drawn once. */
const Base = memo(function Base({ data, name }: { data: ScholarsData; name: MapName }) {
  const v = data.views[name];
  return <>
    <path className="prf-land" fillRule="evenodd" d={v.land} />
    <g className="prf-others">{Object.entries(v.points).filter(([key]) => !key.startsWith("find:")).map(([key, [x, y]]) => <circle key={key} cx={x} cy={y} r={3.2} />)}</g>
  </>;
});

function viewFor(data: ScholarsData, name: MapName, [x, y]: [number, number]): Box {
  const v = data.views[name], w = name === "med" ? 620 : 440, h = w * 0.62;
  return [Math.max(0, Math.min(v.width - w, x - w / 2)), Math.max(0, Math.min(v.height - h, y - h / 2)), w, h];
}

export function ProfileMap({ data, s }: { data: ScholarsData; s: Scholar }) {
  const name: MapName = data.views.med.points[s.id] ? "med" : "world";
  const v = data.views[name], at = v.points[s.id];
  const svg = useRef<SVGSVGElement>(null), last = useRef<{ name: MapName; box: Box } | null>(null);
  const ax = at?.[0], ay = at?.[1];
  useLayoutEffect(() => {
    const el = svg.current;
    if (!el || ax === undefined || ay === undefined) return;
    const box = viewFor(data, name, [ax, ay]), from = last.current?.name === name ? last.current.box : null;
    const set = (b: Box) => { last.current = { name, box: b }; el.setAttribute("viewBox", b.join(" ")); };
    if (!from || reducedMotion()) { set(box); return; }
    const start = performance.now();
    let frame = 0;
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / 520), k = 1 - Math.pow(1 - t, 3);
      set(from.map((a, i) => a + (box[i] - a) * k) as Box);
      if (t < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [data, name, ax, ay]);
  if (!at) return <div className="prf-map" hidden />;
  const [x, y] = at, w = viewFor(data, name, at)[2];
  const finds = data.finds.filter((f) => f.by.includes(s.id) && v.points[`find:${f.id}`]);
  return <div className="prf-map">
    <svg key={name} ref={svg} className="prf-svg" preserveAspectRatio="xMidYMid slice" aria-hidden="true" style={toneStyle(s.field)}>
      <Base data={data} name={name} />
      <g className="prf-me">
        {finds.map((f) => { const [fx, fy] = v.points[`find:${f.id}`]; return <rect key={f.id} className="prf-find" x={fx - 5} y={fy - 5} width={10} height={10} transform={`rotate(45 ${fx} ${fy})`} />; })}
        <circle className="prf-halo" cx={x} cy={y} r={w / 34} /><circle className="prf-dot" cx={x} cy={y} r={w / 110} />
        <text className="prf-label" x={x + w / 40} y={y - w / 52} style={{ fontSize: `${w / 30}px` }}>{s.place[0]}</text>
      </g>
    </svg>
  </div>;
}
